test("deleted rows do not end the export early (CAT-284)", () => {
  const gateway = new MemoryGateway({ invoices: [{id:"i-1",name:"A"},{id:"i-2",name:"B",deleted:true},{id:"i-3",name:"C"}] });
  assert.deepEqual(exportCatalog(gateway, "invoices", {pageSize:2}).entries.map(r=>r.id), ["i-1","i-3"]);
});
test("pages full of deleted rows are skipped", () => {
  const rows = [{id:"1",name:"A",deleted:true},{id:"2",name:"B",deleted:true},{id:"3",name:"C",deleted:true},{id:"4",name:"D"},{id:"5",name:"E"},{id:"6",name:"F",deleted:true}];
  const gateway = new MemoryGateway({ invoices: rows });
  assert.deepEqual(exportCatalog(gateway, "invoices", {pageSize:1}).entries.map(r=>r.id), ["4","5"]);
});
